1, & \mbox{if on-task or level 120 Slayer} \\
0.5, & \mbox{otherwise}
\end{cases} \\
cursed & = \begin{cases}
1.5, & \mbox{if using a cursed ushabti} \\
1, & \mbox{otherwise}
\end{cases} \\
limited & = \begin{cases}
